%[text] # -- Esercitazione 3 -- %%
%[text] \- Esercizio 1 - %
%-- Dati iniziali
f = @(x,y) x.^2 + y.^2; % Funzione data
domF = [
    -1, 1; % Dominio di f sulle x
    -2, 2  % Dominio di f sulle y
];

%-- Densità punti nodali di interpolazione
n = 5; m = 5;
hx = (domF(1,2)-domF(1,1))/(n-1);
hy = (domF(2,2)-domF(2,1))/(m-1);

%-- Definizione dei punti nodali
xNodi = [domF(1,1):hx:domF(1,2)];
yNodi = [domF(2,1):hy:domF(2,2)];

%-- Polinomio di Lagrange per x e per y
xBaseLagrange = lagrangePols(xNodi);
yBaseLagrange = lagrangePols(yNodi, true); %[output:82ec7487] %[output:93502756] %[output:50f574c7] %[output:25d8f740] %[output:0b32bdd1] %[output:5599fdef] %[output:9cdf3dbf] %[output:676706ef] %[output:16b585c2] %[output:06fe10f0]

%- Valori della funzione sui punti nodali
% (Per il calcolo del polinomio interpolatore)
[Xg, Yg] = ndgrid(xNodi, yNodi);
Fg = f(Xg, Yg);

%- Creazione del polinomio interpolatore
syms xSym ySym

polLagrangeSym = sym(0);
for i = 1:numel(xNodi)
    for j = 1:numel(yNodi)
        polLagrangeSym = polLagrangeSym + Fg(i,j) * xBaseLagrange{i}(xSym) * yBaseLagrange{j}(ySym);
    end
end

polLagrangeSym = expand(polLagrangeSym);
disp(polLagrangeSym) %[output:542d199b]

polLagrangeHandle = matlabFunction(polLagrangeSym, 'Vars', [xSym, ySym]);

%-- Visualizzazione della funzione e dell'interpolante
[Xplot, Yplot] = meshgrid(linspace(domF(1,1), domF(1,2), 50), ...
    linspace(domF(2,1), domF(2,2), 50));

figure; %[output:1457ade0]
graf1a = surf(Xplot, Yplot, f(Xplot, Yplot), ... %[output:1457ade0]
    'FaceAlpha', 0.4, 'EdgeColor', 'b', 'FaceColor', 'b'); %[output:1457ade0]
hold on; %[output:1457ade0]

graf1b = surf(Xplot, Yplot, polLagrangeHandle(Xplot, Yplot), ... %[output:1457ade0]
    'FaceAlpha', 0.4, 'EdgeColor', 'none', 'FaceColor', 'r'); %[output:1457ade0]

graf1c = plot3(Xg, Yg, Fg, ... %[output:1457ade0]
    ".k", MarkerSize=15); %[output:1457ade0]

legend([graf1a graf1b graf1c(1)], ... %[output:1457ade0]
    { ... %[output:1457ade0]
        "$f(x,y)$", ... %[output:1457ade0]
        "$p(x,y)$", ... %[output:1457ade0]
        "Punti nodali" ... %[output:1457ade0]
    }, ... %[output:1457ade0]
    Interpreter="latex" ... %[output:1457ade0]
); %[output:1457ade0]
xlabel('x'); %[output:1457ade0]
ylabel('y'); %[output:1457ade0]
zlabel('z'); %[output:1457ade0]
title("Funzione e polinomio approssimante"); %[output:1457ade0]
grid on; %[output:1457ade0]
view(3); %[output:1457ade0]
hold off %[output:1457ade0]

%- Calcolo dell'errore
errore = @(x,y) abs(f(x,y) - polLagrangeHandle(x,y));

errorePlot = errore(Xplot, Yplot);
erroreMassimo = max(errorePlot(:));
fprintf('Errore massimo: %.6e\n', erroreMassimo); %[output:9f18be17]

%-- Visualizzazione dell'errore sull'intera griglia
erroreGriglia = errore(Xplot, Yplot);
figure; %[output:3cdbfcbb]
surf(Xplot, Yplot, erroreGriglia, 'EdgeColor', 'none'); %[output:3cdbfcbb]
hold on; %[output:3cdbfcbb]

plot3(Xg, Yg, errore(Xg, Yg), ".k", MarkerSize=15); %[output:3cdbfcbb]

xlabel('x'); %[output:3cdbfcbb]
ylabel('y'); %[output:3cdbfcbb]
zlabel('$r(x,y) = |f(x,y)-p(x,y)|$', Interpreter='latex'); %[output:3cdbfcbb]
title('Errore del polinomio approssimante'); %[output:3cdbfcbb]
colorbar; %[output:3cdbfcbb]
grid on; %[output:3cdbfcbb]

